<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { createDepartment, createUser, disableDepartment, disableUser, enableDepartment, enableUser, fetchDepartment, fetchDepartmentPage, fetchDepartments, fetchUser, fetchUserPage, updateDepartment, updateUser } from '@/services/organization'
import type { Department, UserAccount } from '@/types/api'

const activeTab = ref('departments'); const departments = ref<Department[]>([]); const users = ref<UserAccount[]>([]); const loading = ref(false)
const departmentVisible = ref(false); const userVisible = ref(false); const editing = ref(false)
const departmentForm = reactive({ id: 0, parentId: undefined as number | undefined, departmentCode: '', departmentName: '', sortOrder: 10 })
const userForm = reactive({ id: 0, departmentId: undefined as number | undefined, username: '', rawPassword: '', displayName: '', email: '', phone: '' })
async function load() { loading.value = true; try { const [departmentPage, userPage, options] = await Promise.all([fetchDepartmentPage({ pageNum: 1, pageSize: 100 }), fetchUserPage({ pageNum: 1, pageSize: 100 }), fetchDepartments()]); departments.value = options.length ? options : departmentPage.records; users.value = userPage.records } finally { loading.value = false } }
function openDepartmentCreate() { editing.value = false; Object.assign(departmentForm, { id: 0, parentId: undefined, departmentCode: '', departmentName: '', sortOrder: 10 }); departmentVisible.value = true }
async function openDepartmentEdit(value: unknown) { const row = value as Department; editing.value = true; const item = await fetchDepartment(row.id); Object.assign(departmentForm, item); departmentVisible.value = true }
async function saveDepartment() { if (!departmentForm.departmentName || (!editing.value && !departmentForm.departmentCode)) return ElMessage.warning('请填写完整部门信息'); if (editing.value) await updateDepartment({ id: departmentForm.id, departmentName: departmentForm.departmentName, sortOrder: departmentForm.sortOrder }); else await createDepartment({ parentId: departmentForm.parentId, departmentCode: departmentForm.departmentCode, departmentName: departmentForm.departmentName, sortOrder: departmentForm.sortOrder }); departmentVisible.value = false; ElMessage.success('部门已保存'); await load() }
async function removeDepartment(value: unknown) { const row = value as Department; await ElMessageBox.confirm(`确认停用 ${row.departmentName}？`); await disableDepartment(row.id); await load() }
async function restoreDepartment(value: unknown) { const row = value as Department; await enableDepartment(row.id); ElMessage.success('部门已启用'); await load() }
function openUserCreate() { editing.value = false; Object.assign(userForm, { id: 0, departmentId: undefined, username: '', rawPassword: '', displayName: '', email: '', phone: '' }); userVisible.value = true }
async function openUserEdit(value: unknown) { const row = value as UserAccount; editing.value = true; const item = await fetchUser(row.id); Object.assign(userForm, { ...item, rawPassword: '' }); userVisible.value = true }
async function saveUser() { if (!userForm.departmentId || !userForm.displayName) return ElMessage.warning('请填写完整用户信息'); if (editing.value) await updateUser({ id: userForm.id, departmentId: userForm.departmentId, displayName: userForm.displayName, email: userForm.email || undefined, phone: userForm.phone || undefined }); else { if (!userForm.username || userForm.rawPassword.length < 8) return ElMessage.warning('用户名必填，密码至少 8 位'); await createUser({ departmentId: userForm.departmentId, username: userForm.username, rawPassword: userForm.rawPassword, displayName: userForm.displayName, email: userForm.email || undefined, phone: userForm.phone || undefined }) } userVisible.value = false; ElMessage.success('用户已保存'); await load() }
async function removeUser(value: unknown) { const row = value as UserAccount; await ElMessageBox.confirm(`确认停用 ${row.displayName}？`); await disableUser(row.id); await load() }
async function restoreUser(value: unknown) { const row = value as UserAccount; await enableUser(row.id); ElMessage.success('用户已启用'); await load() }
onMounted(load)
</script>
<template><main class="workspace-page"><header class="page-heading"><div><span class="section-kicker">ORGANIZATION</span><h1>部门与成员</h1><p>所有数据均自动限定为当前租户。</p></div></header><section class="glass-card module-card"><el-tabs v-model="activeTab"><el-tab-pane label="部门" name="departments"><div class="module-toolbar"><el-button type="primary" @click="openDepartmentCreate">新增部门</el-button></div><el-table v-loading="loading" :data="departments"><el-table-column prop="departmentCode" label="编码" /><el-table-column prop="departmentName" label="名称" /><el-table-column prop="sortOrder" label="排序" width="90" /><el-table-column prop="status" label="状态" width="100" /><el-table-column label="操作" width="150"><template #default="scope"><el-button link @click="openDepartmentEdit(scope.row)">编辑</el-button><el-button v-if="scope.row.status==='DISABLED'" link type="success" @click="restoreDepartment(scope.row)">启用</el-button><el-button v-else link type="danger" @click="removeDepartment(scope.row)">停用</el-button></template></el-table-column></el-table></el-tab-pane>
<el-tab-pane label="用户" name="users"><div class="module-toolbar"><el-button type="primary" @click="openUserCreate">新增用户</el-button></div><el-table v-loading="loading" :data="users"><el-table-column prop="username" label="用户名" /><el-table-column prop="displayName" label="姓名" /><el-table-column prop="departmentId" label="部门 ID" /><el-table-column prop="email" label="邮箱" /><el-table-column prop="status" label="状态" width="100" /><el-table-column label="操作" width="150"><template #default="scope"><el-button link @click="openUserEdit(scope.row)">编辑</el-button><el-button v-if="scope.row.status==='DISABLED'" link type="success" @click="restoreUser(scope.row)">启用</el-button><el-button v-else link type="danger" @click="removeUser(scope.row)">停用</el-button></template></el-table-column></el-table></el-tab-pane></el-tabs></section>
<el-dialog v-model="departmentVisible" :title="editing?'编辑部门':'新增部门'" width="500px"><el-form label-position="top"><el-form-item v-if="!editing" label="部门编码"><el-input v-model="departmentForm.departmentCode" /></el-form-item><el-form-item label="部门名称"><el-input v-model="departmentForm.departmentName" /></el-form-item><el-form-item label="排序"><el-input-number v-model="departmentForm.sortOrder" :min="0" /></el-form-item></el-form><template #footer><el-button @click="departmentVisible=false">取消</el-button><el-button type="primary" @click="saveDepartment">保存</el-button></template></el-dialog>
<el-dialog v-model="userVisible" :title="editing?'编辑用户':'新增用户'" width="560px"><el-form label-position="top"><el-form-item label="部门"><el-select v-model="userForm.departmentId"><el-option v-for="item in departments.filter(d=>d.status==='ACTIVE')" :key="item.id" :label="item.departmentName" :value="item.id" /></el-select></el-form-item><template v-if="!editing"><el-form-item label="用户名"><el-input v-model="userForm.username" /></el-form-item><el-form-item label="初始密码"><el-input v-model="userForm.rawPassword" type="password" show-password /></el-form-item></template><el-form-item label="显示名称"><el-input v-model="userForm.displayName" /></el-form-item><div class="form-grid"><el-form-item label="邮箱"><el-input v-model="userForm.email" /></el-form-item><el-form-item label="电话"><el-input v-model="userForm.phone" /></el-form-item></div></el-form><template #footer><el-button @click="userVisible=false">取消</el-button><el-button type="primary" @click="saveUser">保存</el-button></template></el-dialog></main></template>
